package com.dailydua.tracker.data

/** Short duas. Quran verses: Tanzil Uthmani text, Saheeh International translation. Others are from memory, see each source. */
object MoreDuas {
    val all = listOf(
        Dua(id = "ease-my-task", title = "For confidence and ease in a task", tag = "Rabbi-shrah li sadri · 20:25", time = TimeOfDay.ANYTIME, category = "Success & guidance",
            arabic = "قَالَ رَبِّ ٱشۡرَحۡ لِي صَدۡرِي وَيَسِّرۡ لِيٓ أَمۡرِي وَٱحۡلُلۡ عُقۡدَةࣰ مِّن لِّسَانِي يَفۡقَهُواْ قَوۡلِي",
            transliteration = "Qala rabbi ishrah lee sadree Wayassir lee amree Waohlul AAuqdatan min lisanee Yafqahoo qawlee",
            translation = "[Moses] said, \"My Lord, expand for me my breast [with assurance] And ease for me my task And untie the knot from my tongue That they may understand my speech",
            source = "Quran 20:25-28. Arabic: Tanzil. English: Saheeh International."),
        Dua(id = "good-both-worlds", title = "For good in this life and the next", tag = "Rabbana atina fid-dunya hasanah · 2:201", time = TimeOfDay.ANYTIME, category = "Success & guidance",
            arabic = "وَمِنۡهُم مَّن يَقُولُ رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا حَسَنَةࣰ وَفِي ٱلۡأٓخِرَةِ حَسَنَةࣰ وَقِنَا عَذَابَ ٱلنَّارِ",
            transliteration = "Waminhum man yaqoolu rabbana atina fee alddunya hasanatan wafee alakhirati hasanatan waqina AAathaba alnnari",
            translation = "But among them is he who says, \"Our Lord, give us in this world [that which is] good and in the Hereafter [that which is] good and protect us from the punishment of the Fire",
            source = "Quran 2:201. Arabic: Tanzil. English: Saheeh International."),
        Dua(id = "firm-hearts", title = "For a steadfast heart", tag = "Rabbana la tuzigh qulubana · 3:8", time = TimeOfDay.ANYTIME, category = "Success & guidance",
            arabic = "رَبَّنَا لَا تُزِغۡ قُلُوبَنَا بَعۡدَ إِذۡ هَدَيۡتَنَا وَهَبۡ لَنَا مِن لَّدُنكَ رَحۡمَةًۚ إِنَّكَ أَنتَ ٱلۡوَهَّابُ",
            transliteration = "Rabbana la tuzigh quloobana baAAda ith hadaytana wahab lana min ladunka rahmatan innaka anta alwahhabu",
            translation = "[Who say], \"Our Lord, let not our hearts deviate after You have guided us and grant us from Yourself mercy. Indeed, You are the Bestower",
            source = "Quran 3:8. Arabic: Tanzil. English: Saheeh International."),
        Dua(id = "right-guidance", title = "For right guidance in your affairs", tag = "Rabbana atina min ladunka rahmah · 18:10", time = TimeOfDay.ANYTIME, category = "Success & guidance",
            arabic = "إِذۡ أَوَى ٱلۡفِتۡيَةُ إِلَى ٱلۡكَهۡفِ فَقَالُواْ رَبَّنَآ ءَاتِنَا مِن لَّدُنكَ رَحۡمَةࣰ وَهَيِّئۡ لَنَا مِنۡ أَمۡرِنَا رَشَدࣰا",
            transliteration = "Ith awa alfityatu ila alkahfi faqaloo rabbana atina min ladunka rahmatan wahayyi lana min amrina rashadan",
            translation = "[Mention] when the youths retreated to the cave and said, \"Our Lord, grant us from Yourself mercy and prepare for us from our affair right guidance",
            source = "Quran 18:10. Arabic: Tanzil. English: Saheeh International."),
        Dua(id = "trust-allah", title = "Relying on Allah alone", tag = "Hasbiyallahu la ilaha illa huwa · 9:129", time = TimeOfDay.ANYTIME, category = "Success & guidance",
            arabic = "فَإِن تَوَلَّوۡاْ فَقُلۡ حَسۡبِيَ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۖ عَلَيۡهِ تَوَكَّلۡتُۖ وَهُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ",
            transliteration = "Fain tawallaw faqul hasbiya Allahu la ilaha illa huwa AAalayhi tawakkaltu wahuwa rabbu alAAarshi alAAatheemi",
            translation = "But if they turn away, [O Muhammad], say, \"Sufficient for me is Allah; there is no deity except Him. On Him I have relied, and He is the Lord of the Great Throne",
            source = "Quran 9:129. Arabic: Tanzil. English: Saheeh International."),
        Dua(id = "pious-offspring", title = "For righteous children", tag = "Rabbi hab li min ladunka dhurriyyah · 3:38", time = TimeOfDay.ANYTIME, category = "Family & loved ones",
            arabic = "هُنَالِكَ دَعَا زَكَرِيَّا رَبَّهُۥۖ قَالَ رَبِّ هَبۡ لِي مِن لَّدُنكَ ذُرِّيَّةࣰ طَيِّبَةًۖ إِنَّكَ سَمِيعُ ٱلدُّعَآءِ",
            transliteration = "Hunalika daAAa zakariyya rabbahu qala rabbi hab lee min ladunka thurriyyatan tayyibatan innaka sameeAAu aldduAAai",
            translation = "At that, Zechariah called upon his Lord, saying, \"My Lord, grant me from Yourself a good offspring. Indeed, You are the Hearer of supplication",
            source = "Quran 3:38. Arabic: Tanzil. English: Saheeh International."),
        Dua(id = "righteous-child", title = "Ibrahim’s dua for a child", tag = "Rabbi hab li minas-salihin · 37:100", time = TimeOfDay.ANYTIME, category = "Family & loved ones",
            arabic = "رَبِّ هَبۡ لِي مِنَ ٱلصَّـٰلِحِينَ",
            transliteration = "Rabbi hab lee mina alssaliheena",
            translation = "My Lord, grant me [a child] from among the righteous",
            source = "Quran 37:100. Arabic: Tanzil. English: Saheeh International."),
        Dua(id = "joy-of-eyes", title = "For a loving spouse and children", tag = "Rabbana hab lana min azwajina · 25:74", time = TimeOfDay.ANYTIME, category = "Family & loved ones",
            arabic = "وَٱلَّذِينَ يَقُولُونَ رَبَّنَا هَبۡ لَنَا مِنۡ أَزۡوَٰجِنَا وَذُرِّيَّـٰتِنَا قُرَّةَ أَعۡيُنࣲ وَٱجۡعَلۡنَا لِلۡمُتَّقِينَ إِمَامًا",
            transliteration = "Waallatheena yaqooloona rabbana hab lana min azwajina wathurriyyatina qurrata aAAyunin waijAAalna lilmuttaqeena imaman",
            translation = "And those who say, \"Our Lord, grant us from among our wives and offspring comfort to our eyes and make us an example for the righteous",
            source = "Quran 25:74. Arabic: Tanzil. English: Saheeh International."),
        Dua(id = "gratitude-parents", title = "For gratitude and a righteous family", tag = "Rabbi awziʿni an ashkura · 46:15", time = TimeOfDay.ANYTIME, category = "Family & loved ones",
            arabic = "وَوَصَّيۡنَا ٱلۡإِنسَٰنَ بِوَٰلِدَيۡهِ إِحۡسَٰنًاۖ حَمَلَتۡهُ أُمُّهُۥ كُرۡهࣰا وَوَضَعَتۡهُ كُرۡهࣰاۖ وَحَمۡلُهُۥ وَفِصَٰلُهُۥ ثَلَٰثُونَ شَهۡرًاۚ حَتَّىٰٓ إِذَا بَلَغَ أَشُدَّهُۥ وَبَلَغَ أَرۡبَعِينَ سَنَةࣰ قَالَ رَبِّ أَوۡزِعۡنِيٓ أَنۡ أَشۡكُرَ نِعۡمَتَكَ ٱلَّتِيٓ أَنۡعَمۡتَ عَلَيَّ وَعَلَىٰ وَٰلِدَيَّ وَأَنۡ أَعۡمَلَ صَٰلِحࣰا تَرۡضَىٰهُ وَأَصۡلِحۡ لِي فِي ذُرِّيَّتِيٓۖ إِنِّي تُبۡتُ إِلَيۡكَ وَإِنِّي مِنَ ٱلۡمُسۡلِمِينَ",
            transliteration = "Wawassayna alinsana biwalidayhi ihsanan hamalathu ommuhu kurhan wawadaAAathu kurhan wahamluhu wafisaluhu thalathoona shahran hatta itha balagha ashuddahu wabalagha arbaAAeena sanatan qala rabbi awziAAnee an ashkura niAAmataka allatee anAAamta AAalayya waAAala walidayya waan aAAmala salihan tardahu waaslih lee fee thurriyyatee innee tubtu ilayka wainnee mina almuslimeena",
            translation = "And We have enjoined upon man, to his parents, good treatment. His mother carried him with hardship and gave birth to him with hardship, and his gestation and weaning [period] is thirty months. [He grows] until, when he reaches maturity and reaches [the age of] forty years, he says, \"My Lord, enable me to be grateful for Your favor which You have bestowed upon me and upon my parents and to work righteousness of which You will approve and make righteous for me my offspring. Indeed, I have repented to You, and indeed, I am of the Muslims",
            source = "Quran 46:15. Arabic: Tanzil. English: Saheeh International."),
        Dua(id = "prayer-family", title = "For a family that prays", tag = "Rabbij-ʿalni muqimas-salah · 14:40", time = TimeOfDay.ANYTIME, category = "Family & loved ones",
            arabic = "رَبِّ ٱجۡعَلۡنِي مُقِيمَ ٱلصَّلَوٰةِ وَمِن ذُرِّيَّتِيۚ رَبَّنَا وَتَقَبَّلۡ دُعَآءِ رَبَّنَا ٱغۡفِرۡ لِي وَلِوَٰلِدَيَّ وَلِلۡمُؤۡمِنِينَ يَوۡمَ يَقُومُ ٱلۡحِسَابُ",
            transliteration = "Rabbi ijAAalnee muqeema alssalati wamin thurriyyatee rabbana wtaqabbal duAAai Rabbana ighfir lee waliwalidayya walilmumineena yawma yaqoomu alhisabu",
            translation = "My Lord, make me an establisher of prayer, and [many] from my descendants. Our Lord, and accept my supplication Our Lord, forgive me and my parents and the believers the Day the account is established",
            source = "Quran 14:40-41. Arabic: Tanzil. English: Saheeh International."),
        Dua(id = "mercy-parents", title = "Mercy for your parents", tag = "Rabbir-hamhuma · 17:24", time = TimeOfDay.ANYTIME, category = "Family & loved ones",
            arabic = "وَٱخۡفِضۡ لَهُمَا جَنَاحَ ٱلذُّلِّ مِنَ ٱلرَّحۡمَةِ وَقُل رَّبِّ ٱرۡحَمۡهُمَا كَمَا رَبَّيَانِي صَغِيرࣰا",
            transliteration = "Waikhfid lahuma janaha alththulli mina alrrahmati waqul rabbi irhamhuma kama rabbayanee sagheeran",
            translation = "And lower to them the wing of humility out of mercy and say, \"My Lord, have mercy upon them as they brought me up [when I was] small",
            source = "Quran 17:24. Arabic: Tanzil. English: Saheeh International."),
        Dua(id = "forgive-me-parents", title = "Forgiveness for you and your parents", tag = "Rabbigh-fir li wa li-walidayya · 71:28", time = TimeOfDay.ANYTIME, category = "Family & loved ones",
            arabic = "رَّبِّ ٱغۡفِرۡ لِي وَلِوَٰلِدَيَّ وَلِمَن دَخَلَ بَيۡتِيَ مُؤۡمِنࣰا وَلِلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِۖ وَلَا تَزِدِ ٱلظَّـٰلِمِينَ إِلَّا تَبَارَۢا",
            transliteration = "Rabbi ighfir lee waliwalidayya waliman dakhala baytiya muminan walilmumineena waalmuminati wala tazidi alththalimeena illa tabaran",
            translation = "My Lord, forgive me and my parents and whoever enters my house a believer and the believing men and believing women. And do not increase the wrongdoers except in destruction",
            source = "Quran 71:28. Arabic: Tanzil. English: Saheeh International."),
        Dua(id = "in-need-of-good", title = "When in need of provision", tag = "Rabbi inni lima anzalta · 28:24", time = TimeOfDay.ANYTIME, category = "Provision (rizq)",
            arabic = "فَسَقَىٰ لَهُمَا ثُمَّ تَوَلَّىٰٓ إِلَى ٱلظِّلِّ فَقَالَ رَبِّ إِنِّي لِمَآ أَنزَلۡتَ إِلَيَّ مِنۡ خَيۡرࣲ فَقِيرࣱ",
            transliteration = "Fasaqa lahuma thumma tawalla ila alththilli faqala rabbi innee lima anzalta ilayya min khayrin faqeerun",
            translation = "So he watered [their flocks] for them; then he went back to the shade and said, \"My Lord, indeed I am, for whatever good You would send down to me, in need",
            source = "Quran 28:24. Arabic: Tanzil. English: Saheeh International."),
        Dua(id = "provision-table", title = "Asking Allah to provide", tag = "Allahumma rabbana anzil ʿalayna · 5:114", time = TimeOfDay.ANYTIME, category = "Provision (rizq)",
            arabic = "قَالَ عِيسَى ٱبۡنُ مَرۡيَمَ ٱللَّهُمَّ رَبَّنَآ أَنزِلۡ عَلَيۡنَا مَآئِدَةࣰ مِّنَ ٱلسَّمَآءِ تَكُونُ لَنَا عِيدࣰا لِّأَوَّلِنَا وَءَاخِرِنَا وَءَايَةࣰ مِّنكَۖ وَٱرۡزُقۡنَا وَأَنتَ خَيۡرُ ٱلرَّـٰزِقِينَ",
            transliteration = "Qala AAeesa ibnu maryama allahumma rabbana anzil AAalayna maidatan mina alssamai takoonu lana AAeedan liawwalina waakhirina waayatan minka waorzuqna waanta khayru alrraziqeena",
            translation = "Said Jesus, the son of Mary, \"O Allah, our Lord, send down to us a table [spread with food] from the heaven to be for us a festival for the first of us and the last of us and a sign from You. And provide for us, and You are the best of providers",
            source = "Quran 5:114. Arabic: Tanzil. English: Saheeh International."),
        Dua(id = "admit-fault", title = "Seeking forgiveness, the dua of Adam", tag = "Rabbana zalamna anfusana · 7:23", time = TimeOfDay.ANYTIME, category = "Forgiveness & relief",
            arabic = "قَالَا رَبَّنَا ظَلَمۡنَآ أَنفُسَنَا وَإِن لَّمۡ تَغۡفِرۡ لَنَا وَتَرۡحَمۡنَا لَنَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ",
            transliteration = "Qala rabbana thalamna anfusana wain lam taghfir lana watarhamna lanakoonanna mina alkhasireena",
            translation = "They said, \"Our Lord, we have wronged ourselves, and if You do not forgive us and have mercy upon us, we will surely be among the losers",
            source = "Quran 7:23. Arabic: Tanzil. English: Saheeh International."),
        Dua(id = "relief-distress", title = "In distress, the dua of Yunus", tag = "La ilaha illa anta subhanaka · 21:87", time = TimeOfDay.ANYTIME, category = "Forgiveness & relief",
            arabic = "وَذَا ٱلنُّونِ إِذ ذَّهَبَ مُغَٰضِبࣰا فَظَنَّ أَن لَّن نَّقۡدِرَ عَلَيۡهِ فَنَادَىٰ فِي ٱلظُّلُمَٰتِ أَن لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبۡحَٰنَكَ إِنِّي كُنتُ مِنَ ٱلظَّـٰلِمِينَ",
            transliteration = "Watha alnnooni ith thahaba mughadiban fathanna an lan naqdira AAalayhi fanada fee alththulumati an la ilaha illa anta subhanaka innee kuntu mina alththalimeena",
            translation = "And [mention] the man of the fish, when he went off in anger and thought that We would not decree [anything] upon him. And he called out within the darknesses, \"There is no deity except You; exalted are You. Indeed, I have been of the wrongdoers",
            source = "Quran 21:87. Arabic: Tanzil. English: Saheeh International."),
        Dua(id = "no-burden", title = "The last verse of Al-Baqarah", tag = "Rabbana la tuʾakhidhna · 2:286", time = TimeOfDay.ANYTIME, category = "Forgiveness & relief",
            arabic = "لَا يُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا وُسۡعَهَاۚ لَهَا مَا كَسَبَتۡ وَعَلَيۡهَا مَا ٱكۡتَسَبَتۡۗ رَبَّنَا لَا تُؤَاخِذۡنَآ إِن نَّسِينَآ أَوۡ أَخۡطَأۡنَاۚ رَبَّنَا وَلَا تَحۡمِلۡ عَلَيۡنَآ إِصۡرࣰا كَمَا حَمَلۡتَهُۥ عَلَى ٱلَّذِينَ مِن قَبۡلِنَاۚ رَبَّنَا وَلَا تُحَمِّلۡنَا مَا لَا طَاقَةَ لَنَا بِهِۦۖ وَٱعۡفُ عَنَّا وَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَآۚ أَنتَ مَوۡلَىٰنَا فَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ",
            transliteration = "La yukallifu Allahu nafsan illa wusAAaha laha ma kasabat waAAalayha ma iktasabat rabbana la tuakhithna in naseena aw akhtana rabbana wala tahmil AAalayna isran kama hamaltahu AAala allatheena min qablina rabbana wala tuhammilna ma la taqata lana bihi waoAAfu AAanna waighfir lana wairhamna anta mawlana faonsurna AAala alqawmi alkafireena",
            translation = "Allah does not charge a soul except [with that within] its capacity. It will have [the consequence of] what [good] it has gained, and it will bear [the consequence of] what [evil] it has earned. \"Our Lord, do not impose blame upon us if we have forgotten or erred. Our Lord, and lay not upon us a burden like that which You laid upon those before us. Our Lord, and burden us not with that which we have no ability to bear. And pardon us; and forgive us; and have mercy upon us. You are our protector, so give us victory over the disbelieving people",
            source = "Quran 2:286. Arabic: Tanzil. English: Saheeh International."),
        Dua(id = "rizq-halal", title = "For halal, sufficient provision", tag = "Allahumma-kfini bi-halalika · Tirmidhi", time = TimeOfDay.ANYTIME, category = "Provision (rizq)",
            arabic = "اللَّهُمَّ اكْفِنِي بِحَلَالِكَ عَنْ حَرَامِكَ وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ",
            transliteration = "Allahumma-kfini bi-halalika an haramik, wa aghnini bi-fadlika amman siwak",
            translation = "O Allah, make Your lawful enough for me so that I do not need what is unlawful, and by Your grace make me independent of everyone other than You.",
            source = "Tirmidhi 3563."),
        Dua(id = "rizq-knowledge", title = "For useful knowledge and good provision", tag = "Allahumma inni asʾaluka ʿilman nafiʿa · Ibn Majah", time = TimeOfDay.ANYTIME, category = "Provision (rizq)",
            arabic = "اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا وَرِزْقًا طَيِّبًا وَعَمَلًا مُتَقَبَّلًا",
            transliteration = "Allahumma inni as-aluka ilman nafi'a, wa rizqan tayyiba, wa amalan mutaqabbala",
            translation = "O Allah, I ask You for beneficial knowledge, good provision and accepted deeds.",
            source = "Ibn Majah 925."),
        Dua(id = "ease-hardship", title = "When something feels hard", tag = "Allahumma la sahla illa ma jaʿaltahu sahla", time = TimeOfDay.ANYTIME, category = "Success & guidance",
            arabic = "اللَّهُمَّ لَا سَهْلَ إِلَّا مَا جَعَلْتَهُ سَهْلًا، وَأَنْتَ تَجْعَلُ الْحَزْنَ إِذَا شِئْتَ سَهْلًا",
            transliteration = "Allahumma la sahla illa ma ja'altahu sahla, wa anta taj'alul-hazna idha shi'ta sahla",
            translation = "O Allah, nothing is easy except what You make easy, and You make the difficult easy if You will.",
            source = "Ibn Hibban 974."),
        Dua(id = "anxiety-debt", title = "For worry, sadness and debt", tag = "Allahumma inni aʿudhu bika minal-hamm · Bukhari", time = TimeOfDay.ANYTIME, category = "Forgiveness & relief",
            arabic = "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْجُبْنِ وَالْبُخْلِ، وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ",
            transliteration = "Allahumma inni a'udhu bika minal-hammi wal-hazan, wal-'ajzi wal-kasal, wal-jubni wal-bukhl, wa dala'id-dayni wa ghalabatir-rijal",
            translation = "O Allah, I seek refuge in You from worry and sadness, from weakness and laziness, from cowardice and miserliness, and from the burden of debt and being overpowered by men.",
            source = "Bukhari 6369."),
        Dua(id = "sayyid-istighfar", title = "The best way to ask forgiveness", tag = "Sayyid al-Istighfar · Bukhari", time = TimeOfDay.ANYTIME, category = "Forgiveness & relief",
            arabic = "اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ لَكَ بِذَنْبِي فَاغْفِرْ لِي، فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ",
            transliteration = "Allahumma anta rabbi la ilaha illa ant, khalaqtani wa ana abduk, wa ana ala ahdika wa wa'dika mastata't, a'udhu bika min sharri ma sana't, abu-u laka bi-ni'matika alayya, wa abu-u laka bi-dhanbi fa-ghfir li, fa-innahu la yaghfirudh-dhunuba illa ant",
            translation = "O Allah, You are my Lord, there is no god but You. You created me and I am Your servant, and I keep Your covenant and promise as far as I am able. I seek refuge in You from the evil I have done. I acknowledge Your favour upon me and I acknowledge my sin, so forgive me, for none forgives sins but You.",
            source = "Bukhari 6306."),
        Dua(id = "protect-children", title = "Protection for your children", tag = "Uʿidhukuma bi-kalimatillah · Bukhari", time = TimeOfDay.ANYTIME, category = "Family & loved ones",
            arabic = "أُعِيذُكُمَا بِكَلِمَاتِ اللَّهِ التَّامَّةِ مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ وَمِنْ كُلِّ عَيْنٍ لَامَّةٍ",
            transliteration = "U'idhukuma bi-kalimatillahit-tammati min kulli shaytanin wa hammah, wa min kulli aynin lammah",
            translation = "I seek protection for you both in the perfect words of Allah from every devil and every harmful creature, and from every evil eye.",
            source = "Bukhari 3371."),
        Dua(id = "newlyweds", title = "For a newly married couple", tag = "Barakallahu laka · Abu Dawud", time = TimeOfDay.ANYTIME, category = "Family & loved ones",
            arabic = "بَارَكَ اللَّهُ لَكَ وَبَارَكَ عَلَيْكَ وَجَمَعَ بَيْنَكُمَا فِي خَيْرٍ",
            transliteration = "Barakallahu laka wa baraka alayka wa jama'a baynakuma fi khayr",
            translation = "May Allah bless you, shower blessings upon you, and bring you together in goodness.",
            source = "Abu Dawud 2130, Tirmidhi 1091."),
        Dua(id = "set-right-affairs", title = "For success in faith, life and the Hereafter", tag = "Allahumma aslih li dini · Muslim", time = TimeOfDay.ANYTIME, category = "Success & guidance",
            arabic = "اللَّهُمَّ أَصْلِحْ لِي دِينِي الَّذِي هُوَ عِصْمَةُ أَمْرِي، وَأَصْلِحْ لِي دُنْيَايَ الَّتِي فِيهَا مَعَاشِي، وَأَصْلِحْ لِي آخِرَتِي الَّتِي فِيهَا مَعَادِي، وَاجْعَلِ الْحَيَاةَ زِيَادَةً لِي فِي كُلِّ خَيْرٍ، وَاجْعَلِ الْمَوْتَ رَاحَةً لِي مِنْ كُلِّ شَرٍّ",
            transliteration = "Allahumma aslih li dini alladhi huwa ismatu amri, wa aslih li dunyaya allati fiha ma'ashi, wa aslih li akhirati allati fiha ma'adi, waj'alil-hayata ziyadatan li fi kulli khayr, waj'alil-mawta rahatan li min kulli sharr",
            translation = "O Allah, set right my religion, which is the safeguard of my affairs; set right my worldly life, in which is my livelihood; set right my Hereafter, to which is my return; make life an increase for me in every good, and make death a rest for me from every evil.",
            source = "Muslim 2720."),
    )
}
